.lsr-root[data-theme="light"] [data-name^="Popup/"] > [data-name="Background"]::after{content:"";position:absolute;inset:0;border-radius:inherit;background:color-mix(in srgb, var(--wa-bg, rgb(247 250 254)) 92%, transparent);pointer-events:none}
